from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)
db_path = 'practice.db'

@app.route('/search', methods=['POST'])
def search_user():
    search_term = request.form.get('username', '')

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Query the database with the search term
        query = "SELECT id, username, email FROM users WHERE username LIKE '" + search_term + "%'"
        cursor.execute(query)

        results = cursor.fetchall()
        conn.close()

        return jsonify({
            'success': True,
            'results': [{'id': r[0], 'username': r[1], 'email': r[2]} for r in results]
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
